WITH with_windows AS (SELECT *, ROUND(units / SUM(units) OVER (PARTITION BY store_id), 4) AS units_share, SUM(units) OVER (ORDER BY sale_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_units, LAG(units, 2) OVER (PARTITION BY product_id ORDER BY revenue ASC, id ASC) AS prev_units, NTILE(10) OVER (ORDER BY units DESC, id ASC) AS units_bucket, NTILE(5) OVER (PARTITION BY store_id ORDER BY units DESC, id ASC) AS units_bucket_2 FROM store_sales) SELECT store_id, CASE WHEN units_share >= 0.86 THEN 'PREMIUM' ELSE 'STANDARD' END AS units_share_tier, PERCENTILE_APPROX(prev_units, 0.5) AS prev_units_p50, COUNT(*) AS row_count, CORR(revenue, units) AS corr_revenue_units FROM with_windows GROUP BY store_id, CASE WHEN units_share >= 0.86 THEN 'PREMIUM' ELSE 'STANDARD' END
